source("common.R")
df <- data.frame(a = c(11L, 12L, 13L, 14L), s = c("w", "xx", "yyy", "zzzz"), stringsAsFactors = FALSE)
b <- function(i) arrow::record_batch(data.frame(a = i + 1:4, s = paste0("s", i + 1:4), stringsAsFactors = FALSE))
bytes <- a_stream(list(b(10L), b(20L), b(30L))); m <- msgs(bytes); L <- locate(bytes, m[[2]])
cat("--- bodyLength disagreeing with the buffers / framing (stream, batch 1 of 3)\n")
for (d in c(-48, -8, -1, 1, 8, 16, 2^40, -2^40)) both(put(bytes, L$body_length, get64(bytes, L$body_length) + d), paste("bodyLength +", d))
cat("--- trailing bytes inside the body: 8 extra bytes after the buffers, bodyLength + 8\n")
x <- c(bytes[1:(m[[3]]$start)], raw(8), bytes[(m[[3]]$start + 1):length(bytes)]); x <- put(x, L$body_length, get64(bytes, L$body_length) + 8); both(x, "body has 8 trailing bytes")
cat("--- truncation at every byte: what comes back\n")
res <- vapply(seq_len(length(bytes) - 1), function(n) { z <- try_z(arrow_read(bytes[1:n])); if (is_err(z)) z$cls else paste0("OK", nrow(z)) }, "")
r <- rle(res); print(data.frame(upto = cumsum(r$lengths), result = r$values)); cat("message starts:", vapply(m, function(x) x$start, 0), " total", length(bytes), "\n")
ares <- vapply(c(m[[3]]$start, m[[4]]$start, length(bytes) - 8, length(bytes) - 4), function(n) { z <- a_read(bytes[1:n]); if (is_err(z)) z$msg else paste0("OK", nrow(z)) }, ""); cat("arrow at message boundaries / no EOS / half EOS:", ares, sep = "\n  ")
cat("--- trailing garbage after EOS\n"); both(c(bytes, as.raw(1:13)), "13 bytes after EOS"); both(c(bytes, bytes), "a second stream after EOS")
both(c(bytes[1:(length(bytes) - 8)], bytes), "second schema without EOS between")
cat("--- file\n")
f <- a_file(list(b(10L), b(20L), b(30L))); n <- length(f)
res <- vapply(seq_len(n - 1), function(k) { z <- try_z(arrow_read(f[1:k])); if (is_err(z)) z$cls else paste0("OK", nrow(z)) }, ""); r <- rle(res); print(data.frame(upto = cumsum(r$lengths), result = r$values))
both(c(f, raw(8)), "file + 8 trailing zero bytes"); both(c(f, f), "file twice")
fm <- msgs(f, 8); blk <- vapply(fm[2:4], function(x) ipc_block_at(f, x), 0); cat("blocks at", blk, "\n")
k <- blk[2]  # block of batch 2: offset(8) metaDataLength(4) pad(4) bodyLength(8)
for (v in c(0, 8, fm[[2]]$start, fm[[1]]$start, fm[[3]]$start + 8, n - 10, n, 2^40, -8)) both(put(f, k, v), paste("block2 offset", v))
for (v in c(0, 8, 1000, -1)) both(put(f, k + 8, v, 4), paste("block2 metaDataLength", v))
for (v in c(0, 8, 1000, -1, 2^62)) both(put(f, k + 16, v), paste("block2 bodyLength", v))
cat("--- footer length field\n")
flen <- rd32(f, n - 10); for (v in c(flen - 8, flen + 8, 0, -1, n, 2^31 - 1)) { g <- f; g[(n - 9):(n - 6)] <- le_int(if (v < 0) 2^32 + v else v, 4L); both(g, paste("footer length", v)) }
g <- f; g[n] <- as.raw(0); both(g, "bad trailing magic"); g <- f; g[7:8] <- as.raw(c(1, 2)); both(g, "bytes 7-8 of the leading magic not zero"); g <- f; g[6] <- charToRaw("2"); both(g, "ARROW2")
